#pragma once
const char* dashboardStyle = R"html(
<style>
:root{color-scheme:dark;--bg:#0b1118;--panel:#131d29;--edge:#273648;--muted:#9cacc0;--text:#edf3fa;--accent:#62ddd0}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 system-ui,sans-serif}body>header,body>main,body>details{max-width:1180px;margin:24px auto;padding:0 24px}h1{font-size:28px;letter-spacing:-1px;margin:4px 0}h2{font-size:18px;margin:0 0 16px}p,small{color:var(--muted)}small{display:block;margin:6px 0 18px;max-width:85ch}label{display:block;margin:12px 0 6px}input,select,button{font:inherit;border:1px solid var(--edge);border-radius:8px;padding:10px 12px;background:#0c1622;color:var(--text)}input:not([type=radio]):not([type=submit]){width:100%;max-width:420px}input[type=radio]{accent-color:var(--accent)}button,input[type=submit]{cursor:pointer;background:var(--accent);color:#0a2421;font-weight:650}button:hover,input[type=submit]:hover{filter:brightness(1.1)}button.secondary{background:transparent;color:var(--text)}button.danger{background:#522b33;color:#ffd1d5;border-color:#94505a}:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.topbar,.toolbar,.statusline{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap}.eyebrow{color:var(--accent);font-size:11px;letter-spacing:2px;text-transform:uppercase}.badge{border:1px solid var(--edge);border-radius:99px;padding:5px 12px;color:var(--muted);font-size:13px}.badge.live{color:var(--accent)}.statusline{margin:20px 0;color:var(--muted)}#fault{padding:14px;border:1px solid #a55565;border-radius:10px;background:#42232c;color:#ffd1d5;margin-bottom:16px}#fault:empty{display:none}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card,.plot,.controls,details{background:var(--panel);border:1px solid var(--edge);border-radius:14px}.card{padding:18px}.card label{margin:0;color:var(--muted);font-size:12px}.value{font-size:30px;font-weight:650;font-variant-numeric:tabular-nums;margin:7px 0}.unit{font-size:14px;color:var(--muted)}.sub{font-size:12px;color:var(--muted)}.plot{padding:18px;margin-top:16px}.plot h2{margin:0}.chartbox{height:260px;position:relative}.chartbox.short{height:180px}canvas{display:block;width:100%;height:100%}.legend{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.legend button{background:transparent;color:var(--text);font-size:12px;padding:4px 9px;font-weight:400}.legend button[aria-pressed=false]{opacity:.4}.legend i{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px}.toolbar{margin-top:20px;justify-content:flex-start}.toolbar button,.toolbar select{font-size:13px}.hint{color:var(--muted);font-size:12px}.controls{padding:20px;display:flex;gap:20px;align-items:end;flex-wrap:wrap;margin:20px 0}.controls form{margin:0}.controls>form:first-child{flex:1}.controls small{margin-bottom:0}.control-actions{display:flex;align-items:flex-start;gap:20px;flex-wrap:wrap}body>details{width:calc(100% - 48px);max-width:1132px}details{padding:20px!important}summary{font-size:18px;font-weight:650;cursor:pointer}details[open] summary{margin-bottom:20px}details h2{margin-top:24px}details form{padding-bottom:20px;border-bottom:1px solid var(--edge)}.reading{overflow-wrap:anywhere;color:var(--muted);font:12px ui-monospace,monospace;min-height:20px}body.stale .value{opacity:.4}@media(max-width:700px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}body>header,body>main,body>details{margin:14px 12px;padding:0}body>details{width:auto}h1{font-size:23px}.card{padding:12px}.value{font-size:25px}.chartbox{height:220px}.plot{padding:12px}.controls{align-items:stretch}.controls>form:first-child{flex-basis:100%}}
</style>
)html";
const char* htmlMetrics = R"html(
<div class="statusline"><span>Control <strong id="controlState">Waiting for data</strong></span><span id="lastUpdate">No measurements yet</span></div>
<div id="fault" role="alert"></div>
<div class="cards">
 <div class="card"><label>Upper chamber</label><div class="value"><span id="chamberTemperature">--</span> <span class="unit">&deg;C</span></div><div class="sub">Moonraker sensor</div></div>
 <div class="card"><label>Lower chamber</label><div class="value"><span id="dhtTemperature">--</span> <span class="unit">&deg;C</span></div><div class="sub">DHT20 &middot; <span id="dhtHumiduty">--</span>% RH</div></div>
 <div class="card"><label>Heat exchanger</label><div class="value"><span id="ntcTemperature">--</span> <span class="unit">&deg;C</span></div><div class="sub">NTC &middot; metal temperature</div></div>
 <div class="card"><label>Target</label><div class="value"><span id="targetTemperature">--</span> <span class="unit">&deg;C</span></div><div class="sub">Top / bottom difference: <span id="airDelta">--</span> &deg;C</div></div>
</div>
<div class="toolbar"><label for="range">History</label><select id="range"><option value="300">5 minutes</option><option value="900" selected>15 minutes</option><option value="1800">30 minutes</option></select><button id="pause" class="secondary" type="button">Pause chart</button><button id="export" class="secondary" type="button">Export CSV</button><span class="hint">History is kept in this tab &middot; pause affects charts only</span></div>
<section class="plot"><h2>Temperature</h2><div id="tempLegend" class="legend"></div><div class="chartbox"><canvas id="temperatureChart" role="img" aria-label="Temperature history in degrees Celsius"></canvas></div><div class="reading" id="tempReading">Waiting for measurements...</div></section>
<section class="plot"><div class="topbar"><h2>Heater &amp; fan output</h2><span class="hint">Heater <strong id="heaterDuty">--</strong>% &middot; Fan <strong id="fanDuty">--</strong>%</span></div><div id="powerLegend" class="legend"></div><div class="chartbox short"><canvas id="powerChart" role="img" aria-label="Heater and fan PWM history from zero to 100 percent"></canvas></div><div class="reading" id="powerReading"></div></section>
<script>
(()=>{
'use strict';
const $=id=>document.getElementById(id), finite=Number.isFinite;
const history=[], temperature=[['chamberTemperature','Upper air','#6cbaff'],['dhtTemperature','Lower air','#60dfbc'],['ntcTemperature','Radiator','#ffb16b'],['targetTemperature','Target','#c5a3ff']], power=[['heaterDuty','Heater','#ffb16b'],['fanDuty','Fan','#6cbaff']];
const hidden=new Set();let paused=false, frozen=0,lastMessage=0,socket,reconnect,hoverTime=null;
const time=t=>new Date(t).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'});
function legend(id,series){series.forEach(([key,name,color])=>{const b=document.createElement('button');b.type='button';b.setAttribute('aria-pressed','true');b.innerHTML='<i style="background:'+color+'"></i>'+name;b.onclick=()=>{hidden.has(key)?hidden.delete(key):hidden.add(key);b.setAttribute('aria-pressed',String(!hidden.has(key)));drawAll();};$(id).appendChild(b);});}
legend('tempLegend',temperature);legend('powerLegend',power);
function draw(id,series,percent,readout){
 const canvas=$(id),rect=canvas.getBoundingClientRect(),w=rect.width,h=rect.height,dpr=window.devicePixelRatio||1;
 if(!w||!h)return;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);const c=canvas.getContext('2d');c.scale(dpr,dpr);
 const left=46,right=w-12,top=12,bottom=h-28,end=paused?frozen:Date.now(),start=end-Number($('range').value)*1000;
 const visible=series.filter(s=>!hidden.has(s[0])),points=history.filter(p=>p.t>=start&&p.t<=end);
 let low=0,high=100;if(!percent){const vals=[];points.forEach(p=>visible.forEach(s=>{if(finite(p[s[0]]))vals.push(p[s[0]]);}));if(vals.length){low=Math.floor((Math.min(...vals)-3)/5)*5;high=Math.ceil((Math.max(...vals)+3)/5)*5;}else{low=15;high=75;}}
 const x=t=>left+(t-start)/(end-start)*(right-left),y=v=>bottom-(v-low)/(high-low)*(bottom-top);
 c.font='11px system-ui';c.lineWidth=1;c.fillStyle='#9cacc0';
 for(let i=0;i<=4;i++){const v=low+(high-low)*i/4,yy=y(v);c.strokeStyle='#273648';c.beginPath();c.moveTo(left,yy);c.lineTo(right,yy);c.stroke();c.textAlign='right';c.fillText(v.toFixed(0)+(percent?'%':'\u00b0'),left-7,yy+4);}
 c.textAlign='center';for(let i=0;i<=4;i++){const t=start+(end-start)*i/4;c.textAlign=i===0?'left':i===4?'right':'center';c.fillText(new Date(t).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),x(t),h-7);}
 c.save();c.beginPath();c.rect(left,top,right-left,bottom-top);c.clip();
 visible.forEach(([key,name,color])=>{c.strokeStyle=color;c.lineWidth=2;c.setLineDash(key==='targetTemperature'?[6,5]:[]);c.beginPath();let prev=null;points.forEach(p=>{if(!finite(p[key])){prev=null;return;}if(!prev||p.t-prev.t>3500)c.moveTo(x(p.t),y(p[key]));else c.lineTo(x(p.t),y(p[key]));prev=p;});c.stroke();});c.setLineDash([]);
 let point=points.length?points[points.length-1]:null;if(hoverTime!==null&&points.length){point=points.reduce((a,b)=>Math.abs(a.t-hoverTime)<Math.abs(b.t-hoverTime)?a:b);c.strokeStyle='#75879c';c.beginPath();c.moveTo(x(point.t),top);c.lineTo(x(point.t),bottom);c.stroke();}c.restore();
 $(readout).textContent=point?time(point.t)+'  '+visible.map(([key,name])=>name+': '+(finite(point[key])?point[key].toFixed(1)+(percent?'%':'\u00b0C'):'--')).join(' | '):'Waiting for measurements...';
}
function drawAll(){draw('temperatureChart',temperature,false,'tempReading');draw('powerChart',power,true,'powerReading');}
['temperatureChart','powerChart'].forEach(id=>{const canvas=$(id);canvas.onpointermove=e=>{const r=canvas.getBoundingClientRect(),fraction=Math.max(0,Math.min(1,(e.clientX-r.left-46)/(r.width-58))),end=paused?frozen:Date.now();hoverTime=end-(1-fraction)*Number($('range').value)*1000;drawAll();};canvas.onpointerleave=()=>{hoverTime=null;drawAll();};});
$('range').onchange=drawAll;$('pause').onclick=()=>{paused=!paused;frozen=Date.now();$('pause').textContent=paused?'Resume chart':'Pause chart';$('pause').setAttribute('aria-pressed',String(paused));drawAll();};
$('export').onclick=()=>{const keys=['chamberTemperature','dhtTemperature','ntcTemperature','targetTemperature','heaterDuty','fanDuty','dhtHumiduty','airDelta'];const csv=['timestamp,'+keys.join(','),...history.map(p=>new Date(p.t).toISOString()+','+keys.map(k=>finite(p[k])?p[k]:'').join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='chamber-history.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
function connection(text,live){$('connection').textContent=text;$('connection').classList.toggle('live',live);document.body.classList.toggle('stale',!live);}
function connect(){clearTimeout(reconnect);connection('Connecting',false);socket=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.hostname+':81');socket.onmessage=e=>{let m;try{m=JSON.parse(e.data);}catch(_){return;}if(!m||typeof m!=='object'||!finite(m.targetTemperature))return;lastMessage=Date.now();connection('Live',true);$('lastUpdate').textContent='Updated '+time(lastMessage);['chamberTemperature','dhtTemperature','ntcTemperature','targetTemperature','dhtHumiduty','heaterDuty','fanDuty','airDelta'].forEach(k=>{$(k).textContent=finite(m[k])?m[k].toFixed(1):'--';});$('controlState').textContent=m.controlState||'Unknown';if($('ntcCalibrationSamples')&&finite(m.ntcCalibrationSamples))$('ntcCalibrationSamples').textContent=m.ntcCalibrationSamples;if($('ntcCalibrationStatus')&&typeof m.ntcCalibrationStatus==='string')$('ntcCalibrationStatus').textContent=m.ntcCalibrationStatus;$('fault').textContent=m.fault||'';history.push({...m,t:lastMessage});while(history.length>1800||history.length&&lastMessage-history[0].t>1800000)history.shift();drawAll();};socket.onclose=()=>{connection('Disconnected - retrying',false);reconnect=setTimeout(connect,2000);};socket.onerror=()=>socket.close();}
setInterval(()=>{if(lastMessage&&Date.now()-lastMessage>5000){connection('Data stale',false);$('lastUpdate').textContent='Last update '+time(lastMessage);if(socket&&socket.readyState===WebSocket.OPEN)socket.close();}if(!paused)drawAll();},1000);
window.addEventListener('resize',drawAll);drawAll();connect();
})();
</script>
)html";
